//! 🧪️ The original Progress wire keeps final native cells and pays every interrupted owning frontier.
use super::*;
use pack::record::RetainedRecordBodySourceDecode;
use pack::record::RetainedRecordBodyToken;
use semio_framework_tool_run::testkit::progress_receiving::Phase;
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value::RetainedCloneProgress;
use semio_framework_value::list::PagedList;
use std::mem::MaybeUninit;
use protocol::codec::{OriginalWireSourceIdentity,RetainedWireByteSource};
type Receipt=Option<(RetainedCloneGrant,RetainedCloneProgress)>;
fn counters<'a>(slot:&'a MaybeUninit<ToolRunReceivedProgress>)->&'a PagedList<ToolRunCounter,8>{unsafe{&*std::ptr::addr_of!((*slot.as_ptr()).counters)}}
fn steps<'a>(slot:&'a MaybeUninit<ToolRunReceivedProgress>)->&'a PagedList<ToolRunStep,64>{unsafe{&*std::ptr::addr_of!((*slot.as_ptr()).steps)}}
struct Pages<'a>(&'a[u8]);
impl RetainedWireByteSource for Pages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{OriginalWireSourceIdentity{address:self.0.as_ptr()as usize,extent:self.0.len(),authority:Some((42,7))}}fn byte_at(&self,index:usize)->Option<u8>{self.0.chunks(7).nth(index/7)?.get(index%7).copied()}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(v,(h.requested_bytes,h.released_bytes))}
fn hex(text:&str)->Vec<u8>{text.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn receipt(g:RetainedCloneGrant,p:RetainedCloneProgress,r:Receipt,h:(usize,usize),physical:&mut(usize,usize)){assert_eq!(r,Some((g,p)));assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),h);physical.0+=h.0;physical.1+=h.1}
fn run(row:&serde_json::Value,stop:usize)->usize{
 let bytes=hex(row["bodyHex"].as_str().unwrap());let source=Pages(&bytes);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let m=RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..g};
 let(mut lower,h)=observe(||RetainedRecordBodySourceDecode::admit(&source,(0,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());let mut physical=(0,0);let r=lower.take_receipt().unwrap();receipt(g,r.1,Some(r),h,&mut physical);
 let((mut frame,p),h)=observe(||ToolRunNativeTickPreparation::admit(&lower,ToolRunReceivingLimits::REPORTS,g).unwrap().unwrap());receipt(g,p,frame.take_receipt(),h,&mut physical);let frame_address=frame.native_address().unwrap();for _ in 0..9{let(p,h)=observe(||frame.initialize_header_step(m).unwrap());receipt(m,p,frame.take_receipt(),h,&mut physical)}
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g},RetainedCloneGrant{maximum_capacity_bytes:ToolRunProgressReceiving::birth_bytes()-1,..g}]{let(r,h)=observe(||ToolRunProgressReceiving::admit(&lower,&mut frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}
 let((mut typed,p),h)=observe(||ToolRunProgressReceiving::admit(&lower,&mut frame,g).unwrap().unwrap());receipt(g,p,typed.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical);let address=typed.native_address().unwrap();let(mut pending,mut accepted,mut copied)=(None,0,0);let mut counter_pointers=Vec::new();let mut argument_pointer=None;
 for _ in 0..20000{
  if accepted>=stop||typed.borrowed().is_some(){break}
  assert_eq!(typed.native_address(),Some(address));assert_eq!(frame.native_address(),Some(frame_address));
  let(p,h)=if typed.headers<3{observe(||typed.initialize_header_step(&lower,&frame,m).unwrap().unwrap())}else{
   let d=typed.reserve_demands(&lower,&frame).unwrap();if d.depth>0{for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}]{let(r,h)=observe(||typed.reserve_step(&lower,&frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||typed.reserve_step(&lower,&frame,g).unwrap().unwrap());receipt(g,p,typed.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical);accepted+=1;continue}
   if matches!(typed.phase,Phase::IdentityAdmit|Phase::IdentityInstall|Phase::IdentityClose|Phase::IdentityRemove|Phase::CounterCommit|Phase::StepAdmit|Phase::StepTake|Phase::StepAdopt|Phase::StepClose|Phase::StepRemove){
    if typed.phase==Phase::StepTake{argument_pointer=Some(typed.step.as_ref().unwrap().step().unwrap().args.as_ptr())}
    let d=typed.demands(&lower,&frame,&None).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{let(r,h)=observe(||typed.advance_child_step(&lower,&frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||typed.advance_child_step(&lower,&frame,g).unwrap().unwrap());receipt(g,p,typed.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical);copied+=p.copied_bytes;accepted+=1;
    if typed.headers>=2{let rows=counters(typed.slot.as_ref().unwrap().as_ref());while counter_pointers.len()<rows.len(){counter_pointers.push(rows.backing_ptr(counter_pointers.len()).unwrap())}}
    if typed.headers>=3{let rows=steps(typed.slot.as_ref().unwrap().as_ref());if let Some(step)=rows.last(){assert_eq!(Some(step.args.as_ptr()),argument_pointer)}}continue
   }
   if pending.is_none(){if lower.token().is_some(){let(ok,h)=observe(||lower.take_token_into(&mut pending,g).unwrap());assert!(ok);let r=lower.take_receipt().unwrap();receipt(g,r.1,Some(r),h,&mut physical)}else{let(_,h)=observe(||lower.step(&source,g).unwrap());let r=lower.take_receipt().unwrap();receipt(g,r.1,Some(r),h,&mut physical);continue}}
   if !matches!(pending,Some(RetainedRecordBodyToken::Value(_))){assert!(matches!(pending,Some(RetainedRecordBodyToken::Catalog{symbols:0}|RetainedRecordBodyToken::CatalogComplete)));pending.take();continue}
   let before=pending;let d=typed.demands(&lower,&frame,&pending).unwrap();for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:d.depth-1,..g}),if d.copy_bytes>0{Some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}else{None},if d.capacity_bytes>0{Some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}else{None}].into_iter().flatten(){let(r,h)=observe(||typed.receive(&lower,&frame,&mut pending,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0));assert_eq!(pending,before)}
   let(p,h)=observe(||typed.receive(&lower,&frame,&mut pending,g).unwrap().unwrap());assert!(typed.receive(&lower,&frame,&mut pending,g).unwrap().is_none());receipt(g,p,typed.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical);copied+=p.copied_bytes;accepted+=1;for(index,pointer)in counter_pointers.iter().enumerate(){assert_eq!(counters(typed.slot.as_ref().unwrap().as_ref()).backing_ptr(index),Some(*pointer))}continue
  };receipt(m,p,typed.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical);accepted+=1;
 }
 if stop==usize::MAX{
  let value=typed.borrowed().expect("original Progress must complete within its finite action bound");assert_eq!(value.sequence,row["sequence"].as_u64().unwrap());assert_eq!(value.state.ordinal(),row["state"].as_u64().unwrap()as u8);assert_eq!(value.stage,row["stage"].as_u64().unwrap()as u16);assert_eq!(value.completed,row["completed"].as_u64().unwrap());assert_eq!(value.total,row["total"].as_u64());assert_eq!(value.units_per_second,row["unitsPerSecond"].as_f64().unwrap()as f32);assert_eq!(value.conflicts,row["conflicts"].as_u64().unwrap()as u32);assert_eq!(value.counters.len(),row["counters"].as_array().unwrap().len());assert_eq!(value.counters.capacity(),value.counters.len());assert_eq!(value.steps.len(),row["stepCount"].as_u64().unwrap()as usize);assert_eq!(value.steps.capacity(),value.steps.len());for(index,counter)in row["counters"].as_array().unwrap().iter().enumerate(){assert_eq!(value.counters[index].counter,counter["counter"].as_u64().unwrap()as u16);assert_eq!(value.counters[index].value,counter["value"].as_u64().unwrap())}
  if !value.steps.is_empty(){let corpus:serde_json::Value=serde_json::from_str(crate::fixture_text("🧪️tests/🧫️fixtures/🎞️ticks.json")).unwrap();let reference=crate::ToolRunTick::decode(&hex(corpus["ticks"][0]["hex"].as_str().unwrap())).unwrap();assert_eq!(&value.steps[0],reference.progress.unwrap().steps.iter().next().unwrap());assert_eq!(Some(value.steps[0].args.as_ptr()),argument_pointer)}
  let mut recipient=None;let(p,h)=observe(||typed.publish_into(&lower,&frame,&mut recipient,m).unwrap().unwrap());assert_eq!(h,(0,0));assert!(typed.terminal_is_empty());assert_eq!(recipient.as_ref().unwrap().native_address(),Some(address));assert!(recipient.as_ref().unwrap().borrowed().is_none());receipt(m,p,recipient.as_mut().unwrap().take_receipt(&lower,&mut frame).unwrap(),h,&mut physical);let received=recipient.as_mut().unwrap();assert_eq!(received.borrowed().unwrap()as *const _ as usize,address);received.cancel();while !received.terminal_is_empty(){let d=received.close_demands().unwrap();if d.release_bytes>0{let(r,h)=observe(||received.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||received.close_step(g).unwrap().unwrap());receipt(g,p,received.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical)}let(_,h)=observe(||drop(recipient));assert_eq!(h,(0,0));
 }else{
  frame.cancel();assert_eq!(frame.close_demands(),Default::default());typed.cancel();while !typed.terminal_is_empty(){let d=typed.close_demands().unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{let(r,h)=observe(||typed.close_step(&lower,&frame,denied).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}if d.release_bytes>0{let(r,h)=observe(||typed.close_step(&lower,&frame,RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}).unwrap());assert!(r.is_none());assert_eq!(h,(0,0))}let(p,h)=observe(||typed.close_step(&lower,&frame,g).unwrap().unwrap());receipt(g,p,typed.take_receipt(&lower,&mut frame).unwrap(),h,&mut physical)}
 }
 frame.cancel();while !frame.terminal_is_empty(){let(p,h)=observe(||frame.close_step(g).unwrap());receipt(g,p,frame.take_receipt(),h,&mut physical)}lower.cancel();while !lower.terminal_is_empty(){if lower.token().is_some(){pending.take();assert!(lower.take_token_into(&mut pending,g).unwrap());lower.take_receipt().unwrap();pending.take();}let(_,h)=observe(||lower.close_step(g).unwrap());let r=lower.take_receipt().unwrap();receipt(g,r.1,Some(r),h,&mut physical)}assert_eq!(physical.0,physical.1);let(_,h)=observe(||{drop(typed);drop(frame);drop(lower)});assert_eq!(h,(0,0));accepted
}
#[test]
fn original_progress_receiving_keeps_final_slot_counter_and_argument_pointers_at_every_paid_frontier(){let law:serde_json::Value=serde_json::from_str(crate::fixture_text("🎞️tick/🛬️receive/📊️progress/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["interruptPolicy"],"every-paid-frontier");for row in law["cases"].as_array().unwrap(){let turns=run(row,usize::MAX);for stop in 0..=turns{run(row,stop);}}}
